#include <bits/stdc++.h>
using namespace std; using ll=long long;
ll cd(ll a,ll b){if(a>=0)return(a+b-1)/b;return-((-a)/b);} 
ll Uof(ll D,ll t,ll k){D=abs(D);if(!D)return 0;if(!k)return D%t? (ll)1e18:D/t;vector<ll> c{0};ll a=D/t,b=D/(t+k);for(ll z:{a,b})for(ll m=z-2;m<=z+2;m++)if(m>=0)c.push_back(m);ll ans=1e18;for(ll m:c){ll q=max({0LL,cd(m*t-D,k),cd(D-m*(t+k),k)});ans=min(ans,m+2*q);}return ans;}
pair<ll,ll> pr(ll r,ll D,ll t,ll k){ll A=2*t+k;return{max(0LL,cd(r*t+D,A)),min(r,(r*(t+k)+D)/A)};}
int main(){mt19937 rng(7);for(int it=0;it<2000000;it++){int t=1+rng()%100,k=2+rng()%99;int lo=2*t+1,hi=min(500,2*t+k-1);if(lo>hi)continue;int L=lo+rng()%(hi-lo+1),a=1+rng()%L;int Umax=min(t+k,L-1);vector<int>d(L+1,-1),par(L+1,-1);set<int>s;for(int i=1;i<=L;i++)s.insert(i);queue<int>q;d[a]=0;s.erase(a);q.push(a);while(!q.empty()){int x=q.front();q.pop();for(auto[l,r]:vector<pair<int,int>>{{x-Umax,x-t},{x+t,x-Umax?x+Umax:x+Umax}}){l=max(l,1);r=min(r,L);auto it=s.lower_bound(l);while(it!=s.end()&&*it<=r){int y=*it;d[y]=d[x]+1;par[y]=x;it=s.erase(it);q.push(y);}}}for(int b=1;b<=L;b++){if(b==a)continue;ll D=abs(b-a),U=Uof(D,t,k);if(d[b]-U==2){auto p=pr(U+1,D,t,k);if(p.first<=p.second){cout<<"FOUND L="<<L<<" a="<<a<<" b="<<b<<" t="<<t<<" k="<<k<<" f="<<d[b]<<" U="<<U<<" pU1="<<p.first<<","<<p.second<<"\n";vector<int>path;int x=b;while(x!=-1){path.push_back(x);x=par[x];}reverse(path.begin(),path.end());cout<<"path";for(int v:path)cout<<" "<<v;cout<<"\n";return 0;}}}}cout<<"none\n";}
